</template>

<script setup>
import { computed } from 'vue';

const props = defineProps({
  variant: {
    type: String,
    default: 'imagotipo', // 'imagotipo' | 'isotipo' | 'logotipo'
  },
  direction: {
    type: String,
    default: 'horizontal', // 'horizontal' | 'vertical'
  },
  theme: {
    type: String,
    default: 'light', // 'light' | 'inverted' | 'dark' | 'monochrome' | 'orange'
  },
  size: {
    type: String,
    default: 'medium', // 'small' | 'sm' | 'medium' | 'md' | 'large' | 'lg' | 'xl'
  },
});

const normalizedSize = computed(() => {
  const s = (props.size || '').toLowerCase();
  if (s === 'sm' || s === 'small') return 'small';
  if (s === 'lg' || s === 'large') return 'large';
  if (s === 'xl') return 'xl';
  return 'medium';
});

const computedHeight = computed(() => {
  switch (normalizedSize.value) {
    case 'small':
      return 22;
    case 'large':
      return 36;
    case 'xl':
      return 48;
    default:
      return 28;
  }
});

const computedWidth = computed(() => {
  return Math.round(computedHeight.value * 4.5);
});

const iconDimension = computed(() => {
  return computedHeight.value;
});

const isMonochromeTheme = computed(() => {
  const t = (props.theme || '').toLowerCase();
  return t === 'monochrome' || t === 'flame';
});

const isInvertedTheme = computed(() => {
  const t = (props.theme || '').toLowerCase();
  return t === 'inverted' || t === 'dark';
});

const centerFillColor = computed(() => {
  if (isMonochromeTheme.value || props.theme === 'orange') return 'var(--color-canvas-base)';
  return 'var(--color-brand-base)';
});

const tipFillColor = computed(() => {
  if (isMonochromeTheme.value) return 'var(--color-canvas-base)';
  if (props.theme === 'orange') return 'var(--color-rescue-base)';
  return 'var(--color-brand-light-base)';
});

const wordmarkColor = computed(() => {
  if (isInvertedTheme.value || isMonochromeTheme.value || props.theme === 'orange') {
    return 'var(--color-canvas-base)';
  }
  return 'var(--color-content-base)';
});

const dotColor = computed(() => {
  if (isMonochromeTheme.value) return 'var(--color-canvas-base)';
  if (props.theme === 'orange') return 'var(--color-rescue-base)';
  return 'var(--color-brand-base)';
});
</script>
